parameters.functionCode:
// Compile analytics data
const platformMetrics = $items('Fetch Daily Metrics');
const aiCosts = $items('Fetch AI Costs');
const ga4Data = $items('GA4 Analytics');

// Calculate totals
let totalPosts = 0;
let totalEngagement = 0;
let totalCost = 0;
let totalRevenue = 0;

// Process platform metrics
const platformSummary = {};
platformMetrics.forEach(row => {
  const platform = row.json.platform;
  platformSummary[platform] = {
    posts: parseInt(row.json.total_posts),
    avgViralScore: parseFloat(row.json.avg_viral_score || 0),
    avgEngagement: parseFloat(row.json.avg_engagement || 0),
    likes: parseInt(row.json.total_likes || 0),
    shares: parseInt(row.json.total_shares || 0),
    views: parseInt(row.json.total_views || 0),
    highPerformers: parseInt(row.json.high_performers || 0)
  };
  totalPosts += platformSummary[platform].posts;
  totalEngagement += platformSummary[platform].avgEngagement * platformSummary[platform].posts;
});

// Process AI costs
const modelCosts = {};
aiCosts.forEach(row => {
  const model = row.json.model_name;
  modelCosts[model] = {
    requests: parseInt(row.json.requests),
    avgLatency: parseFloat(row.json.avg_latency || 0),
    totalCost: parseFloat(row.json.total_cost || 0),
    avgQuality: parseFloat(row.json.avg_quality || 0),
    failures: parseInt(row.json.failures || 0)
  };
  totalCost += modelCosts[model].totalCost;
});

// Process GA4 data if available
if (ga4Data && ga4Data.length > 0) {
  ga4Data.forEach(row => {
    totalRevenue += parseFloat(row.json.totalRevenue || 0);
  });
}

// Calculate ROI
const roi = totalCost > 0 ? ((totalRevenue - totalCost) / totalCost * 100).toFixed(2) : 0;
const avgEngagementRate = totalPosts > 0 ? (totalEngagement / totalPosts).toFixed(4) : 0;

// Get top performing content
const topPerformers = [];
Object.entries(platformSummary).forEach(([platform, metrics]) => {
  if (metrics.highPerformers > 0) {
    topPerformers.push({
      platform,
      count: metrics.highPerformers,
      avgEngagement: metrics.avgEngagement
    });
  }
});
topPerformers.sort((a, b) => b.avgEngagement - a.avgEngagement);

return [{
  json: {
    date: new Date().toISOString(),
    summary: {
      totalPosts,
      avgEngagementRate,
      totalCost: totalCost.toFixed(2),
      totalRevenue: totalRevenue.toFixed(2),
      roi: `${roi}%`,
      topPlatform: topPerformers[0]?.platform || 'none'
    },
    platformMetrics: platformSummary,
    modelCosts,
    topPerformers,
    recommendations: this.generateRecommendations(platformSummary, modelCosts)
  }
}];

function generateRecommendations(platforms, models) {
  const recommendations = [];

  // Platform recommendations
  Object.entries(platforms).forEach(([platform, metrics]) => {
    if (metrics.avgEngagement < 0.02) {
      recommendations.push(`${platform}: Engagement below 2% - consider refreshing content strategy`);
    }
    if (metrics.avgViralScore < 50) {
      recommendations.push(`${platform}: Low viral scores - review trending topics`);
    }
  });

  // Model recommendations
  Object.entries(models).forEach(([model, metrics]) => {
    if (metrics.failures > metrics.requests * 0.1) {
      recommendations.push(`${model}: High failure rate (${((metrics.failures/metrics.requests)*100).toFixed(1)}%) - check API limits`);
    }
    if (metrics.avgLatency > 5000) {
      recommendations.push(`${model}: Slow response times - consider alternatives`);
    }
  });

  return recommendations;
}

